INSERT INTO press_source (source_id, organization_id, method, adapter, homepage_url, endpoint_url, allowed_hosts, interval_minutes, verification_status, verification_note, endpoint_verified_at, policy_basis, registry_version) VALUES ('src:mohw:press-rss', 'org:mohw', 'RSS', 'RSSAdapter', 'https://www.mohw.go.kr', 'https://www.mohw.go.kr/rss/board.es?mid=a10503000000&bid=0027&info', '["www.mohw.go.kr"]', 60, 'ENDPOINT_VERIFIED', '2026-10-03 RSS 2.0 응답과 item 파싱을 직접 확인했고, robots.txt가 이 RSS 경로를 명시적으로 Allow한다. 보건복지부 정보구독 페이지(menu.es?mid=a10807000000)가 같은 주소를 안내한다.', 1791032932, 'robots.txt Allow와 공식 RSS 안내만 확인했다. 공공누리 유형 등 개별 이용조건과 공개 표시 권한은 운영자 확인 전이라 승인 대기 상태다.', 'seed-dataset-2026-10-03');
